"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { getAnalytics } from "@/analytics";
import { useAttribution } from "@/analytics/store";
import { config } from "@/config";
import { getDeviceType } from "@/lib/session";
import type { FallbackTrigger, HandoffContext, Route } from "@/lib/types";
import { buildWhatsAppUrl } from "@/lib/whatsapp";
import { FallbackPanel } from "./FallbackPanel";

interface HandoffProps {
  /** Placement from the route; superseded by the persisted cookie value. */
  placement: string;
  /**
   * Server-rendered `href` so the anchor is valid with JavaScript disabled
   * (C-7). It is returned verbatim during hydration so the attribute matches
   * exactly; only once the client store has the real cookie do we rebuild it
   * to append the discount code.
   */
  baseHref: string;
  ctaLocation?: "landing" | "sticky" | "property";
  label: string;
  className?: string;
}

function toContext(
  placement: string,
  discountCode: string | null,
  route: Route,
): HandoffContext {
  return {
    placement,
    discountCode,
    route,
    config: {
      whatsappNumber: config.NEXT_PUBLIC_WHATSAPP_NUMBER,
      discountPercent: config.NEXT_PUBLIC_DISCOUNT_PERCENT,
    },
  };
}

/**
 * FR-10 / FR-11 / FR-13 — the primary CTA and its fallback.
 *
 * Behaviour by device:
 *  - **Mobile:** the native navigation is left intact (the `<a>` remains
 *    authoritative, so it still works without JS), with a `FALLBACK_TIMEOUT_MS`
 *    safety net that opens the panel if the page is still visible — meaning
 *    nothing happened.
 *  - **Desktop:** navigation is intercepted and the fallback panel is shown
 *    directly (Flow C), since `wa.me` would otherwise just navigate the tab
 *    away to WhatsApp Web with no copyable option.
 *
 * `whatsapp_click` fires on activation either way (C-1: attempt, not verified
 * success). Sessions that also emit `fallback_shown` are excluded from the
 * stricter `G1_strict` metric — see architect spec §10.3.
 *
 * Derived state comes from `useSyncExternalStore` rather than an effect, so
 * there is no `setState`-in-effect and no hydration mismatch.
 */
export function Handoff({
  placement,
  baseHref,
  ctaLocation = "landing",
  label,
  className,
}: HandoffProps) {
  const attr = useAttribution();
  const [fallback, setFallback] = useState<FallbackTrigger | null>(null);
  const anchorRef = useRef<HTMLAnchorElement>(null);
  const timerRef = useRef<number | null>(null);

  const { href, ctx } = useMemo(() => {
    // Hydration: the server has no cookie, so reproduce its href byte-for-byte.
    if (!attr) {
      return {
        href: baseHref,
        ctx: toContext(placement, null, placement ? "qr" : "direct"),
      };
    }

    const route: Route = attr.ref === "qr" ? "qr" : "direct";
    const next = toContext(attr.placement, attr.code || null, route);
    return { href: buildWhatsAppUrl(next), ctx: next };
  }, [attr, baseHref, placement]);

  useEffect(
    () => () => {
      if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    },
    [],
  );

  const handleClick = useCallback(
    (event: React.MouseEvent<HTMLAnchorElement>) => {
      getAnalytics().track("whatsapp_click", {
        cta_location: ctaLocation,
        has_property_ref: false,
      });

      const onVisibility = () => {
        if (document.visibilityState === "hidden" && timerRef.current !== null) {
          window.clearTimeout(timerRef.current);
          timerRef.current = null;
          document.removeEventListener("visibilitychange", onVisibility);
        }
      };

      if (getDeviceType(navigator.userAgent) === "desktop") {
        // FR-13 — desktop gets explicit options rather than a blind redirect.
        event.preventDefault();
        setFallback("desktop");
        getAnalytics().track("fallback_shown", { trigger: "desktop" });
        return;
      }

      // Mobile: let the browser navigate. If WhatsApp opens, the page goes
      // background → `visibilitychange` clears the timer. If nothing happens,
      // the page stays visible and the panel opens instead (no dead end).
      timerRef.current = window.setTimeout(
        () => {
          timerRef.current = null;
          document.removeEventListener("visibilitychange", onVisibility);
          if (document.visibilityState === "visible") {
            setFallback("deeplink_fail");
            getAnalytics().track("fallback_shown", { trigger: "deeplink_fail" });
          }
        },
        config.NEXT_PUBLIC_FALLBACK_TIMEOUT_MS,
      );
      document.addEventListener("visibilitychange", onVisibility);
    },
    [ctaLocation],
  );

  const closeFallback = useCallback(() => {
    setFallback(null);
    anchorRef.current?.focus();
  }, []);

  return (
    <>
      <a
        ref={anchorRef}
        href={href}
        onClick={handleClick}
        className={className}
        rel="noopener"
      >
        {label}
      </a>
      {fallback ? (
        <FallbackPanel trigger={fallback} ctx={ctx} onClose={closeFallback} />
      ) : null}
    </>
  );
}
