"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import { fallback as fallbackCopy } from "@/data/content/fallback";
import { format } from "@/lib/format";
import type { FallbackTrigger, HandoffContext } from "@/lib/types";
import { buildShortLink, buildWebWhatsAppUrl } from "@/lib/whatsapp";

interface FallbackPanelProps {
  trigger: FallbackTrigger;
  ctx: HandoffContext;
  onClose: () => void;
}

/**
 * FR-13 — "no dead ends".
 *
 * Appears without a page reload when WhatsApp cannot be opened. Provides a
 * web entry point, a copyable short link, and the discount code for manual
 * relay. Meets NFR-5: focus moves in on open, Escape closes, focus is trapped
 * while open, and the copy result is announced via `aria-live`.
 */

/** Clipboard API → hidden textarea → visible selection (NFR-8, secure-context). */
async function copyText(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    /* fall through to the legacy path */
  }

  try {
    const textarea = document.createElement("textarea");
    textarea.value = text;
    textarea.setAttribute("readonly", "");
    textarea.style.position = "fixed";
    textarea.style.opacity = "0";
    document.body.appendChild(textarea);
    textarea.select();
    const ok = document.execCommand("copy");
    document.body.removeChild(textarea);
    return ok;
  } catch {
    return false;
  }
}

export function FallbackPanel({ trigger, ctx, onClose }: FallbackPanelProps) {
  const panelRef = useRef<HTMLDivElement>(null);
  const [status, setStatus] = useState("");
  const [copied, setCopied] = useState(false);

  const shortLink = buildShortLink(ctx.config.whatsappNumber);
  const webUrl = buildWebWhatsAppUrl(ctx);

  // Move focus into the dialog on open (NFR-5).
  useEffect(() => {
    panelRef.current?.focus();
  }, []);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "Escape") {
        event.stopPropagation();
        onClose();
        return;
      }
      if (event.key !== "Tab") return;

      const focusables = panelRef.current?.querySelectorAll<HTMLElement>(
        'a[href], button:not([disabled])',
      );
      if (!focusables || focusables.length === 0) return;

      const first = focusables[0]!;
      const last = focusables[focusables.length - 1]!;
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    },
    [onClose],
  );

  const handleCopy = useCallback(async () => {
    const ok = await copyText(shortLink);
    setCopied(ok);
    setStatus(ok ? fallbackCopy.copySuccess : fallbackCopy.copyFailed);
  }, [shortLink]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-black/50 p-4 sm:items-center"
      onClick={(event) => {
        if (event.target === event.currentTarget) onClose();
      }}
    >
      <div
        ref={panelRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby="fallback-title"
        aria-describedby="fallback-desc"
        tabIndex={-1}
        onKeyDown={handleKeyDown}
        className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl outline-none dark:bg-zinc-900 dark:text-zinc-50"
      >
        <h2
          id="fallback-title"
          className="text-lg font-semibold text-zinc-900 dark:text-zinc-50"
        >
          {trigger === "desktop"
            ? fallbackCopy.titleDesktop
            : fallbackCopy.titleDeeplinkFail}
        </h2>

        <p id="fallback-desc" className="mt-2 text-sm text-zinc-600 dark:text-zinc-400">
          {fallbackCopy.description}
        </p>

        <a
          href={webUrl}
          className="mt-5 flex w-full items-center justify-center rounded-xl bg-emerald-700 px-4 py-3 text-sm font-semibold text-white hover:bg-emerald-800"
        >
          {fallbackCopy.openInBrowser}
        </a>

        <button
          type="button"
          onClick={handleCopy}
          className="mt-3 flex w-full items-center justify-center rounded-xl border border-zinc-300 px-4 py-3 text-sm font-semibold text-zinc-800 hover:bg-zinc-50 dark:border-zinc-700 dark:text-zinc-100 dark:hover:bg-zinc-800"
        >
          {copied ? fallbackCopy.copiedLabel : fallbackCopy.copyLink}
        </button>

        <p className="mt-3 break-all rounded-lg bg-zinc-100 px-3 py-2 font-mono text-xs text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300">
          {shortLink}
        </p>

        {ctx.discountCode ? (
          <p className="mt-3 text-sm text-zinc-600 dark:text-zinc-400">
            {format(fallbackCopy.discountCodeLabel, {
              percent: ctx.config.discountPercent,
            })}{" "}
            <span className="font-mono font-semibold text-zinc-900 dark:text-zinc-50">
              {ctx.discountCode}
            </span>
          </p>
        ) : null}

        <p aria-live="polite" className="mt-2 min-h-5 text-sm text-emerald-700 dark:text-emerald-400">
          {status}
        </p>

        <button
          type="button"
          onClick={onClose}
          className="mt-3 w-full rounded-xl px-4 py-2 text-sm font-medium text-zinc-600 hover:bg-zinc-100 dark:text-zinc-400 dark:hover:bg-zinc-800"
        >
          {fallbackCopy.close}
        </button>
      </div>
    </div>
  );
}
