"use client";

import { useAttribution } from "@/analytics/store";
import { DiscountBanner } from "./DiscountBanner";

/**
 * FR-15 / C-4 — shows the discount banner on routes that did NOT server-render
 * it (Flow D: a returning QR visitor landing on `/`, `/offer` or `/privacy`).
 *
 * Two properties matter:
 *  - it renders NOTHING unless the cookie says `ref: "qr"`, so a non-QR visitor
 *    never has discount markup in their DOM (FR-15 acceptance criteria);
 *  - it appears/disappears purely from the `useSyncExternalStore` snapshot —
 *    server, hydration and first client render all agree it is absent, so
 *    there is no hydration mismatch and, being `fixed`, no layout shift
 *    (NFR-1).
 */
export function BannerInjector() {
  const attr = useAttribution();

  if (attr?.ref !== "qr") return null;

  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-0 z-40 px-4 pb-4 sm:px-6">
      <div className="pointer-events-auto mx-auto max-w-3xl">
        <DiscountBanner />
      </div>
    </div>
  );
}
